void Prepare()
{
  std::chrono::seconds sec(1);
  rclcpp::Rate r(sec);

  // Open serial port
  while (rclcpp::ok() && !imu_.Open(device_)) {
    RCLCPP_WARN(this->get_logger(), "Keep trying to open [%s] in 1 second period...",
                device_.c_str());
    r.sleep();
  }

  // Stop any ongoing telemetry and flush
  imu_.StopTelemetry();
  std::this_thread::sleep_for(std::chrono::milliseconds(100));

  // Read settings to get sensitivity and product info
  int retry = 3;
  bool settings_ok = false;
  for (int i = 0; i < retry && rclcpp::ok(); i++) {
    if (imu_.ReadSettings()) {
      settings_ok = true;
      break;
    }
    RCLCPP_WARN(this->get_logger(), "Failed to read settings, retry %d/%d...", i + 1, retry);
    r.sleep();
  }

  if (settings_ok) {
    auto& s = imu_.GetSettings();
    RCLCPP_INFO(this->get_logger(), "Product: %s", imu_.GetProductIdStr().c_str());
    RCLCPP_INFO(this->get_logger(), "Build date: %u", s.build_date);
    RCLCPP_INFO(this->get_logger(), "Sample rate: %u Hz", s.sample_rate);
    RCLCPP_INFO(this->get_logger(), "Filter: %u, Grav corr: %u", s.filter_select,
                s.grav_corr_en);
    RCLCPP_INFO(this->get_logger(), "Accel sensitivity: %lu, Gyro sensitivity: %lu",
                static_cast<unsigned long>(s.accl_sensitivity),
                static_cast<unsigned long>(s.gyro_sensitivity));
    updater_->setHardwareID(imu_.GetProductIdStr());
  } else {
    RCLCPP_ERROR(this->get_logger(), "Could not read settings! Sensitivity values may be wrong.");
    updater_->setHardwareID("UNKNOWN");
  }

  // Start telemetry
  if (!imu_.StartTelemetry()) {
    RCLCPP_ERROR(this->get_logger(), "Failed to start telemetry!");
  }
}
// GOUDA_USB_RECONNECT_V1: retry only the configured device, never scan other ports.
void PublishDisconnected()
{
  std_msgs::msg::String msg;
  msg.data = R"({"state":"disconnected","hardware_synchronized":false,"timestamp_basis":"unavailable","usb_offset_bias_unresolved":true})";
  clock_status_pub_->publish(msg);
}

void Disconnect()
{
  imu_.Close();
  clock_mapper_.Reset();
  have_last_imu_counter_ = false;
  last_imu_counter_ = 0;
  last_mcu_time_us_ = 0;
  have_pps_low_ = false;
  last_pps_level_ = false;
  cant_rcv_cnt_ = 1;
  imu_error_ = false;
  next_connect_ = std::chrono::steady_clock::now() + std::chrono::seconds(1);
  PublishDisconnected();
}

void Prepare()
{
  const auto now = std::chrono::steady_clock::now();
  if (!rclcpp::ok() || now < next_connect_) return;
  PublishDisconnected();
  imu_.Close();
  if (!imu_.Open(device_)) {
    RCLCPP_WARN(this->get_logger(), "IMU disconnected; retrying configured device in 1 second: %s", device_.c_str());
    Disconnect();
    return;
  }
  imu_.StopTelemetry();
  std::this_thread::sleep_for(std::chrono::milliseconds(100));
  if (!rclcpp::ok() || !imu_.ReadSettings()) {
    RCLCPP_WARN(this->get_logger(), "IMU settings unavailable; withholding samples and reconnecting");
    Disconnect();
    return;
  }
  const auto& s = imu_.GetSettings();
  if (!s.accl_sensitivity || !s.gyro_sensitivity || (s.mpu_error & kMpuErrImuNotFound)) {
    RCLCPP_ERROR(this->get_logger(), "Invalid IMU settings; withholding samples and reconnecting");
    Disconnect();
    return;
  }
  RCLCPP_INFO(this->get_logger(), "IMU connected: %s; sample rate %u Hz; relearning measurement clock", imu_.GetProductIdStr().c_str(), s.sample_rate);
  updater_->setHardwareID(imu_.GetProductIdStr());
  if (!imu_.StartTelemetry()) {
    Disconnect();
    return;
  }
  last_fresh_measurement_ = std::chrono::steady_clock::now();
  cant_rcv_cnt_ = 1;
}

std::chrono::steady_clock::time_point next_connect_{};
std::chrono::steady_clock::time_point last_fresh_measurement_{};
int cant_rcv_cnt_;

if (imu_.GetState() != AdisRcvBin::State::RUNNING) {
  Prepare();
  return;
}
if (std::chrono::steady_clock::now() - last_fresh_measurement_ > std::chrono::milliseconds(1500)) {
  RCLCPP_WARN(this->get_logger(), "No fresh IMU measurement for 1.5 s; reconnecting configured device");
  Disconnect();
  return;
}

