int AdisRcvBin::ReadSerial()
{
  constexpr int kReadBufSize = 1024;
  uint8_t buf[kReadBufSize];
  int rcv_cnt = read(fd_, buf, kReadBufSize);

  if (rcv_cnt <= 0) {
    return rcv_cnt;
  }

  for (int i = 0; i < rcv_cnt; i++) {
    ring_buf_[ring_write_pos_] = buf[i];
    ring_write_pos_ = (ring_write_pos_ + 1) % kBinRingBufSize;
    if (ring_data_count_ < kBinRingBufSize) {
      ring_data_count_++;
    }
  }

  return rcv_cnt;
}
int AdisRcvBin::ReadSerial()
{
  // Drain the queued burst so slow ROS publish rates do not accumulate old samples.
  // Each first read is bounded by VTIME, and the drain has a finite byte budget.
  constexpr int kReadBufSize = 1024;
  uint8_t buf[kReadBufSize];
  int total = 0;
  for (int burst = 0; burst < 64; ++burst) {
    const int count = read(fd_, buf, kReadBufSize);
    if (count <= 0) return total > 0 ? total : count;
    for (int i = 0; i < count; ++i) {
      ring_buf_[ring_write_pos_] = buf[i];
      ring_write_pos_ = (ring_write_pos_ + 1) % kBinRingBufSize;
      if (ring_data_count_ < kBinRingBufSize) ++ring_data_count_;
    }
    total += count;
    int pending = 0;
    if (ioctl(fd_, FIONREAD, &pending) < 0 || pending <= 0) break;
  }
  return total;
}
